import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { TabInfo, TabsWithFilters } from 'components';
import { createTab } from 'utils/tab';

import {
  PHI_BREADCRUMB_PAGE_NAME_I18N_ID,
  PORTFOLIO_HEALTH_INDEX_PAGE_NAME,
  PORTFOLIO_HEALTH_INDEX_PATH,
  PORTFOLIO_HEALTH_INDEX_TAB_ID_OVERVIEW,
  PORTFOLIO_HEALTH_INDEX_VISIBLE_FILTER_FIELDS,
} from './constants';
import { Overview } from './tabs';

export const PortfolioHealthIndex: React.FC = () => {
  const { formatMessage } = useIntl();

  const tabs = useMemo<TabInfo[]>(
    () => [
      createTab(
        PORTFOLIO_HEALTH_INDEX_TAB_ID_OVERVIEW,
        'Overview',
        <Overview dataTestId="tabpanel-overview" />,
        false,
      ),
    ],
    [],
  );

  return (
    <TabsWithFilters
      filter={{
        pageName: PORTFOLIO_HEALTH_INDEX_PAGE_NAME,
        visibleFields: [...PORTFOLIO_HEALTH_INDEX_VISIBLE_FILTER_FIELDS],
      }}
      tabConfig={{
        tabs,
        baseRoute: PORTFOLIO_HEALTH_INDEX_PATH,
      }}
      dataTestId="portfolio-health-index"
      breadcrumbsList={[
        {
          href: '/portfolio-brand',
          pageName: formatMessage({ id: 'Pillars.pageName.portfolioBrand' }),
        },
        {
          href: PORTFOLIO_HEALTH_INDEX_PATH,
          pageName: formatMessage({ id: PHI_BREADCRUMB_PAGE_NAME_I18N_ID }),
        },
      ]}
      isResponsivePage
    />
  );
};
